CREATE TABLE IF NOT EXISTS "user" (id text PRIMARY KEY, name text NOT NULL, email text UNIQUE NOT NULL, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "session" (id text PRIMARY KEY, "expiresAt" timestamptz NOT NULL, token text UNIQUE NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "ipAddress" text, "userAgent" text, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE INDEX auth_session_user_idx ON "session"("userId");
CREATE TABLE IF NOT EXISTS account (id text PRIMARY KEY, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, scope text, password text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX account_user ON account("userId");
CREATE TABLE IF NOT EXISTS verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "rateLimit" (id text PRIMARY KEY, key text UNIQUE NOT NULL, count integer NOT NULL, "lastRequest" bigint NOT NULL);
CREATE TABLE admins (user_id text PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE);
CREATE TABLE customers (id uuid PRIMARY KEY, user_id text UNIQUE REFERENCES "user"(id) ON DELETE SET NULL, name text NOT NULL, email text UNIQUE NOT NULL, revoked boolean NOT NULL DEFAULT false, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE setup_tokens (hash text PRIMARY KEY, customer_id uuid NOT NULL REFERENCES customers(id), expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE website_versions (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, state text NOT NULL CHECK(state IN ('draft','published')), content jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_content_per_state ON website_versions(state);
CREATE TABLE packages (id uuid PRIMARY KEY, data jsonb NOT NULL, visible boolean NOT NULL DEFAULT true, accepting boolean NOT NULL DEFAULT true, archived boolean NOT NULL DEFAULT false);
CREATE TABLE resource (id integer PRIMARY KEY CHECK(id=1), settings jsonb NOT NULL);
CREATE TABLE bookings (id uuid PRIMARY KEY, package_id uuid REFERENCES packages(id) ON DELETE SET NULL, snapshot jsonb NOT NULL, name text NOT NULL, email text NOT NULL, phone text NOT NULL, message text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, reserved tstzrange NOT NULL, state text NOT NULL CHECK(state IN ('pending','confirmed','declined','cancelled','expired')), expires_at timestamptz NOT NULL, idempotency_key uuid UNIQUE NOT NULL, request_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at>starts_at), EXCLUDE USING gist (reserved WITH &&) WHERE (state IN ('pending','confirmed')));
CREATE INDEX booking_time ON bookings(starts_at);
CREATE TABLE galleries (id uuid PRIMARY KEY, customer_id uuid NOT NULL REFERENCES customers(id), title text NOT NULL, session_date date NOT NULL, expires_at timestamptz NOT NULL, revoked boolean NOT NULL DEFAULT false, state text NOT NULL DEFAULT 'processing' CHECK(state IN ('processing','ready','failed','pending-cleanup','deleted')), version integer NOT NULL DEFAULT 0, zip_key text, zip_bytes bigint NOT NULL DEFAULT 0, error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX gallery_customer ON galleries(customer_id);
CREATE TABLE assets (id uuid PRIMARY KEY, gallery_id uuid REFERENCES galleries(id), scope text NOT NULL CHECK(scope IN ('public','client')), key text UNIQUE NOT NULL, preview_key text, filename text NOT NULL, mime text NOT NULL, bytes bigint NOT NULL CHECK(bytes>=0), preview_bytes bigint NOT NULL DEFAULT 0, reserved_bytes bigint NOT NULL DEFAULT 0, width integer, height integer, alt text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'processing' CHECK(status IN ('processing','ready','failed','pending-cleanup','deleted')), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX asset_gallery ON assets(gallery_id);
CREATE TABLE storage (id integer PRIMARY KEY CHECK(id=1), allowance bigint NOT NULL CHECK(allowance>0));
CREATE TABLE jobs (id uuid PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('gallery','cleanup','asset-cleanup','telegram')), payload jsonb NOT NULL, state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','running','done','failed')), attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), locked_at timestamptz, error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX job_queue ON jobs(state,available_at);
CREATE TABLE outbox (id uuid PRIMARY KEY, dedupe text UNIQUE NOT NULL, recipient text NOT NULL, kind text NOT NULL, payload jsonb NOT NULL, state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','preview','accepted','delivered','failed')), attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), provider_id text, error text, html text, plain text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_attempts (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, outbox_id uuid NOT NULL REFERENCES outbox(id), state text NOT NULL, error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE conversations (id uuid PRIMARY KEY, token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE chat_messages (id uuid PRIMARY KEY, conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, sender text NOT NULL CHECK(sender IN ('visitor','team')), body text NOT NULL, state text NOT NULL DEFAULT 'queued', telegram_message_id bigint UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX chat_conversation ON chat_messages(conversation_id,created_at);
CREATE TABLE telegram_updates (id bigint PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor text NOT NULL, action text NOT NULL, target text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rate_limits (key text PRIMARY KEY, count integer NOT NULL, resets_at timestamptz NOT NULL);
